     "constraint": "制約の詳細", "exception": "例外",
     "exception_condition": "例外が起きる条件"}
  ],
  "institutions": [{"name": "組織・制度", "role": "役割"}],
  "geography": ["canon の場所 ID と一致させる"],
  "disclosure": [{"info": "開示する情報", "chapter": "実在する章 ID"}],
  "notes": ""
}
